import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source: fused tall-skinny x wide-skinny matmul kernel
# A: (M, K)  B: (K, M)  C: (M, M)
# K is small (e.g. 32), M is large (e.g. 32768)
cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_tall_skinny_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K)
{
    extern __shared__ float As[];

    int row = blockIdx.x;
    int col = blockIdx.y * blockDim.x + threadIdx.x;

    // Load the row of A (length K) into shared memory once per block
    if (threadIdx.x < K) {
        As[threadIdx.x] = A[row * K + threadIdx.x];
    }
    __syncthreads();

    if (col < M) {
        float sum = 0.0f;
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            sum += As[k] * B[k * M + col];
        }
        C[row * M + col] = sum;
    }
}

torch::Tensor matmul_tall_skinny_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");

    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);
    int M2 = B.size(1);
    TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
    TORCH_CHECK(M2 == M, "Output must be square (M x M) for this optimized kernel");

    auto C = torch::empty({M, M}, A.options());

    const int threads = 256;
    dim3 block(threads);
    dim3 grid(M, (M + threads - 1) / threads);

    size_t shared_mem_size = K * sizeof(float);

    matmul_tall_skinny_kernel<<<grid, block, shared_mem_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_tall_skinny_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_tall_skinny",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_tall_skinny_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for tall-skinny x wide-skinny matmul.
    A: (M, K), B: (K, M) -> C: (M, M), where K is small compared to M.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        A = A.cuda() if not A.is_cuda else A
        B = B.cuda() if not B.is_cuda else B
        return matmul_module.matmul_tall_skinny_cuda(A, B)


M = 16384 * 2
N = 16 * 2

def get_inputs():
    A = torch.rand(M, N)
    B = torch.rand(N, M)
    return [A, B]

def get_init_inputs():
    return []

